export interface Item { id: number; label: string }

export class Worker0<T extends Item> {
  private seen: T[] = [];
  note = 'item 0 😀 done';
  async run(item: T, extra = 0): Promise<string> {
    this.seen.push(item);
    if (item.id < 0) throw new RangeError(`bad id ${item.id} in worker 0`);
    return (await Promise.resolve(item.label)) + this.note + extra;
  }
}

export class Worker1<T extends Item> {
  private seen: T[] = [];
  note = 'item 1 😀 done';
  async run(item: T, extra = 1): Promise<string> {
    this.seen.push(item);
    if (item.id < 0) throw new RangeError(`bad id ${item.id} in worker 1`);
    return (await Promise.resolve(item.label)) + this.note + extra;
  }
